    rows = len(grid)
    cols = len(grid[0])
    output = [[5]*cols for _ in range(rows)]

    # Mark cells that form continuous diagonals going SE
    for r in range(rows):
        for c in range(cols):
            current = grid[r][c]

            # Check SE continuation
            se_exists = True
            if r + 1 < rows:
